import random
rng = random.Random(9)
size = 7
grid = [[0] * size for _ in range(size)]
topples = 0
def topple_all():
    global topples
    changed = True
    while changed:
        changed = False
        for y in range(size):
            for x in range(size):
                if grid[y][x] >= 4:
                    grid[y][x] -= 4
                    topples += 1
                    changed = True
                    for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < size and 0 <= ny < size:
                            grid[ny][nx] += 1
for _ in range(50):
    grid[rng.randrange(size)][rng.randrange(size)] += 1
    topple_all()
for row in grid:
    print(row)
print('total topples:', topples)
